package com.animame.editor

import org.json.JSONArray
import org.json.JSONObject

object DocumentCodec {
 fun encode(d:AnimationDocument):String{val r=JSONObject();r.put("version",3);r.put("name",d.name);r.put("width",d.width);r.put("height",d.height);r.put("fps",d.fps);r.put("duration",d.duration);r.put("currentFrame",d.currentFrame);r.put("playbackStart",d.playbackStart);r.put("playbackEnd",d.playbackEnd);r.put("audioPath",d.audioPath);r.put("audioStartFrame",d.audioStartFrame);r.put("audioOffsetMs",d.audioOffsetMs);r.put("audioVolume",d.audioVolume.toDouble());r.put("onion",JSONObject().apply{put("enabled",d.onion.enabled);put("previous",d.onion.previousCount);put("next",d.onion.nextCount);put("opacity",d.onion.opacity);put("tintPrevious",d.onion.tintPrevious);put("tintNext",d.onion.tintNext)});r.put("camera",camera(d.camera));r.put("cameraKeys",JSONArray().apply{d.cameraKeys.forEach{put(JSONObject().apply{put("frame",it.frame);put("camera",camera(it.camera))})}});r.put("layers",JSONArray().apply{d.layers.forEach{l->put(JSONObject().apply{put("id",l.id);put("name",l.name);put("visible",l.visible);put("locked",l.locked);put("opacity",l.opacity.toDouble());put("blendMode",l.blendMode);put("frames",JSONArray().apply{l.frames.entries.sortedBy{it.key}.forEach{(n,f)->put(JSONObject().apply{put("frame",n);put("id",f.id);put("exposure",f.exposure);put("rasterPath",f.rasterPath);put("strokes",strokes(f.strokes))})}})})}});return r.toString()}
 fun decode(json:String):AnimationDocument{val r=JSONObject(json);val d=AnimationDocument(name=r.optString("name","Untitled"),width=r.optInt("width",1280),height=r.optInt("height",720),fps=r.optInt("fps",24),duration=r.optInt("duration",1),currentFrame=r.optInt("currentFrame",0),playbackStart=r.optInt("playbackStart",0),playbackEnd=r.optInt("playbackEnd",0),audioPath=r.optString("audioPath","").ifEmpty{null},audioStartFrame=r.optInt("audioStartFrame",0),audioOffsetMs=r.optLong("audioOffsetMs",0L),audioVolume=r.optDouble("audioVolume",1.0).toFloat());d.layers.clear();val ls=r.optJSONArray("layers")?:JSONArray();for(i in 0 until ls.length()){val o=ls.getJSONObject(i);val l=AnimationLayer(id=o.optString("id",java.util.UUID.randomUUID().toString()),name=o.optString("name","Layer"),visible=o.optBoolean("visible",true),locked=o.optBoolean("locked",false),opacity=o.optDouble("opacity",1.0).toFloat(),blendMode=o.optString("blendMode","NORMAL"));val fs=o.optJSONArray("frames")?:JSONArray();for(j in 0 until fs.length()){val f=fs.getJSONObject(j);val df=DrawingFrame(id=f.optString("id",java.util.UUID.randomUUID().toString()),exposure=f.optInt("exposure",1),rasterPath=f.optString("rasterPath","").ifEmpty{null});df.strokes+=decodeStrokes(f.optJSONArray("strokes"));l.frames[f.optInt("frame",0)]=df};d.layers+=l};if(d.layers.isEmpty())d.layers+=AnimationLayer(name="Layer 1");r.optJSONObject("onion")?.let{o->d.onion.enabled=o.optBoolean("enabled",true);d.onion.previousCount=o.optInt("previous",2);d.onion.nextCount=o.optInt("next",2);d.onion.opacity=o.optInt("opacity",50);d.onion.tintPrevious=o.optBoolean("tintPrevious",true);d.onion.tintNext=o.optBoolean("tintNext",true)};copyCamera(r.optJSONObject("camera"),d.camera);val keys=r.optJSONArray("cameraKeys")?:JSONArray();for(i in 0 until keys.length()){val k=keys.getJSONObject(i);val c=AnimationCamera();copyCamera(k.optJSONObject("camera"),c);d.cameraKeys+=CameraKeyframe(k.optInt("frame"),c)};d.normalize();return d}
 private fun camera(c:AnimationCamera)=JSONObject().apply{put("x",c.x.toDouble());put("y",c.y.toDouble());put("scale",c.scale.toDouble());put("rotation",c.rotation.toDouble())}
 private fun copyCamera(o:JSONObject?,c:AnimationCamera){if(o==null)return;c.x=o.optDouble("x",0.0).toFloat();c.y=o.optDouble("y",0.0).toFloat();c.scale=o.optDouble("scale",1.0).toFloat();c.rotation=o.optDouble("rotation",0.0).toFloat()}
 private fun strokes(list:List<StrokeData>)=JSONArray().apply{list.forEach{s->put(JSONObject().apply{put("id",s.id);put("brushId",s.brushId);put("color",s.color);put("size",s.size.toDouble());put("opacity",s.opacity.toDouble());put("settings",settings(s.brushSettings));put("samples",JSONArray().apply{s.samples.forEach{p->put(JSONObject().apply{put("x",p.x.toDouble());put("y",p.y.toDouble());put("pressure",p.pressure.toDouble());put("timeMs",p.timeMs);put("tilt",p.tilt.toDouble());put("orientation",p.orientation.toDouble())})}})})}}
 private fun decodeStrokes(a:JSONArray?):List<StrokeData>{if(a==null)return emptyList();val out=ArrayList<StrokeData>(a.length());for(i in 0 until a.length()){val o=a.getJSONObject(i);val brush=o.optString("brushId","basic");val ps=o.optJSONArray("samples")?:JSONArray();val sm=mutableListOf<StrokeSample>();for(j in 0 until ps.length()){val p=ps.getJSONObject(j);sm+=StrokeSample(p.optDouble("x").toFloat(),p.optDouble("y").toFloat(),p.optDouble("pressure",1.0).toFloat(),p.optLong("timeMs",0),p.optDouble("tilt",0.0).toFloat(),p.optDouble("orientation",0.0).toFloat())};val bs=decodeSettings(o.optJSONObject("settings"),BrushDefaults.forPreset(brush));out+=StrokeData(id=o.optString("id").ifEmpty{java.util.UUID.randomUUID().toString()},brushId=brush,color=o.optInt("color",0xFF000000.toInt()),size=o.optDouble("size",bs.size.toDouble()).toFloat(),opacity=o.optDouble("opacity",bs.opacity.toDouble()).toFloat(),brushSettings=bs,samples=sm)};return out}
 private fun settings(s:BrushSettings)=JSONObject().apply{put("sizeMin",s.sizeMin.toDouble());put("sizeMax",s.sizeMax.toDouble());put("flow",s.flow.toDouble());put("alpha",s.alpha.toDouble());put("hardness",s.hardness.toDouble());put("feather",s.feather.toDouble());put("spacing",s.spacing.toDouble());put("fade",s.fade.toDouble());put("fadeIn",s.fadeIn.toDouble());put("fadeOut",s.fadeOut.toDouble());put("jitter",s.jitter.toDouble());put("pressureSize",s.pressureSize.toDouble());put("pressureOpacity",s.pressureOpacity.toDouble());put("pressureFlow",s.pressureFlow.toDouble());put("tiltSize",s.tiltSize.toDouble());put("tiltOpacity",s.tiltOpacity.toDouble());put("angle",s.angle.toDouble());put("roundness",s.roundness.toDouble());put("lockAlpha",s.lockAlpha);put("eraser",s.eraser);put("antialias",s.antialias)}
 private fun decodeSettings(o:JSONObject?,d:BrushSettings):BrushSettings{if(o==null)return d;return d.copy(sizeMin=o.optDouble("sizeMin",d.sizeMin.toDouble()).toFloat(),sizeMax=o.optDouble("sizeMax",d.sizeMax.toDouble()).toFloat(),flow=o.optDouble("flow",d.flow.toDouble()).toFloat(),alpha=o.optDouble("alpha",d.alpha.toDouble()).toFloat(),hardness=o.optDouble("hardness",d.hardness.toDouble()).toFloat(),feather=o.optDouble("feather",d.feather.toDouble()).toFloat(),spacing=o.optDouble("spacing",d.spacing.toDouble()).toFloat(),fade=o.optDouble("fade",d.fade.toDouble()).toFloat(),fadeIn=o.optDouble("fadeIn",d.fadeIn.toDouble()).toFloat(),fadeOut=o.optDouble("fadeOut",d.fadeOut.toDouble()).toFloat(),jitter=o.optDouble("jitter",d.jitter.toDouble()).toFloat(),pressureSize=o.optDouble("pressureSize",d.pressureSize.toDouble()).toFloat(),pressureOpacity=o.optDouble("pressureOpacity",d.pressureOpacity.toDouble()).toFloat(),pressureFlow=o.optDouble("pressureFlow",d.pressureFlow.toDouble()).toFloat(),tiltSize=o.optDouble("tiltSize",d.tiltSize.toDouble()).toFloat(),tiltOpacity=o.optDouble("tiltOpacity",d.tiltOpacity.toDouble()).toFloat(),angle=o.optDouble("angle",d.angle.toDouble()).toFloat(),roundness=o.optDouble("roundness",d.roundness.toDouble()).toFloat(),lockAlpha=o.optBoolean("lockAlpha",d.lockAlpha),eraser=o.optBoolean("eraser",d.eraser),antialias=o.optBoolean("antialias",d.antialias)).normalized()}
}
